(1 + y)^{5} = 1 + 5y +10y^{2} + 10y^{3} + 5y^{4} + y^{5} \text{ (Jibu.)}
Kwa kutumia nadharia ya binomial tunapata, (1 + y)^{5}
= \binom{5}{0} y^{0} + \binom{5}{1} y^{1} + \binom{5}{2} y^{2} + \binom{5}{3} y^{3} + \binom{5}{4} y^{4} + \binom{5}{5} y^{5}
= 1.1 + \frac{5}{1} y + \frac{5.4}{1.2} y^{2} + \frac{5.4.3}{1.2.3} y^{3} + \frac{5.4.3.2}{1.2.3.4} y^{4} + 1.y^{5}
= 1 + 5y + 10y^{2} + 10y^{3} + 5y^{4} + y^{5} \text{ (Jibu.)}
Kwa kutumia upanuzi wa (1 + y)^{5}
(1) (1 - y)^{5} = \{1 + (-y)\}^{5}
= 1 + 5(-y) + 10(-y)^{2} + 10(-y)^{3} + 5(-y)^{4} + (-y)^{5}
= 1 - 5y + 10y^{2} - 10y^{3} + 5y^{4} - y^{5} \text{ (Jibu.)}

Imepewa, ABCD ni kipeo mraba. AC na BD ni dayagonali mbili zake. Tunatakiwa kuonyesha vektari \vec{AB} na \vec{AC} kwa kuzieleza katika vipengele vya \vec{AD} na \vec{BD} na pia kuonyesha kwamba,
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ na } \vec{AC} - \vec{BD} = 2\vec{AB}.

Katika pembetatu \Delta ABD,
\vec{AD} = \vec{AB} + \vec{BD} \text{ [sheria ya pembetatu]}
\therefore \vec{AB} = \vec{AD} - \vec{BD} \text{.............(i)}
Tena katika pembetatu ACD, \vec{AC} = \vec{AD} + \vec{DC} \text{[sheria ya pembetatu]}
\text{[kwani, ABCD ni kipeo mraba, hivyo } \vec{DC} = \vec{AB}]
= \vec{AD} + \vec{AD} - \vec{BD} [\because \vec{AB} = \vec{AD} - \vec{BD}]
\therefore \vec{AC} = 2\vec{AD} - \vec{BD} \text{.............(ii)}
Sasa, \vec{AC} + \vec{BD} = 2\vec{AD} - \vec{BD} + \vec{BD}
\text{[tunaongeza } \vec{BD} \text{ pande zote mbili za (ii)]}
= 2 \vec{AD}
\therefore \vec{AC} + \vec{BD} = 2 \vec{BC} \text{.............(iii)}
\text{[kwani, ABCD ni kipeo mraba, hivyo } \vec{AD} = \vec{BC}]
Tena, \vec{AC} - \vec{BD} = (2\vec{AD} - \vec{BD}) - \vec{BD} \text{ [Kwa kutumia (ii)]}
= 2\vec{AD} - 2 \vec{BD} = 2 (\vec{AD} - \vec{BD})
= 2\vec{AB} \text{ [Kwa kutumia (i)]}
\therefore \vec{AC} - \vec{BD} = 2\vec{AB} \text{.............(iv)}
Sasa, kutoka katika milinganyo (i), (ii), (iii) na (iv) tunapata,
\vec{AB} = \vec{AD} - \vec{BD}
\vec{AC} = 2\vec{AD} - \vec{BD}
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ na } \vec{AC} - \vec{BD} = 2\vec{AB} \text{ (Imeonyeshwa)}

Inahitajika kuonyesha kwamba, } -(\underline{a} + \underline{b}) = -\underline{a} - \underline{b}
\text{Sasa, } -(\underline{a} + \underline{b}) = (-1) (\underline{a} + \underline{b})
= (-1) \underline{a} + (-1) \underline{b} \text{ [sheria ya usambazaji]}
= -\underline{a} - \underline{b}
\therefore -(\underline{a} + \underline{b}) = -\underline{a} - \underline{b} \text{ (Imeonyeshwa)}

\text{Kutokana na, } \underline{a} + \underline{b} = \underline{c}
\text{Inahitajika kuonyesha kwamba, } \underline{a} = \underline{c} - \underline{b}
\text{Kutokana na, } \underline{a} + \underline{b} = \underline{c}
\text{au, } \underline{a} + \underline{b} - \underline{b} = \underline{c} - \underline{b} \text{ [kuongeza } (-\underline{b}) \text{ pande zote mbili]}
\text{au, } \underline{a} + \underline{0} = \underline{c} - \underline{b}
\therefore \underline{a} = \underline{c} - \underline{b}
\text{Kinyume chake,}
\underline{a} = \underline{c} - \underline{b}
